package com.yjw.vultr;
import android.widget.*;
import org.json.*;
final class CloudScreen {
 final MainActivity a;CloudScreen(MainActivity a){this.a=a;}
 void open(){a.enterDetail("固定订阅","订阅",()->render());}
 static JSONObject record(JSONObject cfg){try{return new JSONObject().put("url",cfg.optString("url")).put("label","Cloudflare 固定订阅").put("phase","fixed");}catch(Exception e){return new JSONObject();}}
 void render(){a.body.removeAllViews();CloudMonitor.card(a,()->render());JSONObject cfg=CloudPublisher.config(a.manager);if(cfg!=null){LinearLayout c=a.card("客户端与发布", "导入到客户端与发布更新是两个独立操作。");a.pair(c,"导入到 FlClash",MainActivity.Tone.PRIMARY,()->SubscriptionActions.flclash(a,record(cfg)),"更多",()->a.menu("固定订阅操作",new String[]{"用于电脑 Clash Verge","复制固定订阅地址","发布最近已就绪节点","选择收藏合并 / 发布","升级当前订阅分流（保留节点）","恢复升级前固定订阅","修改固定入口设置"},()->SubscriptionActions.desktop(a,record(cfg)),()->a.copySubscription(record(cfg)),()->publish(),()->new SubscriptionsScreen(a).mergePicker(),()->upgrade(),()->restoreRouting(),()->edit()));}a.helpCard("固定入口说明","保留同一个 Worker 和只读密钥，URL 就保持不变。自动发布开启时，新节点通过核验后替换已有配置；这会覆盖此前合并内容。发布成功后客户端仍需手动或定时刷新订阅，管家不能读取客户端当前配置。\n连接失败不能判定 Cloudflare 故障；检测耗时不是代理延迟。");}
 void upgrade(){new android.app.AlertDialog.Builder(a).setTitle("升级当前固定订阅分流？").setMessage("保留所有节点和固定地址，备份后替换规则与 DNS；客户端下次刷新生效。不会重装服务器或切换 VPN。").setNegativeButton("取消",null).setPositiveButton("升级",(d,w)->a.task("备份、验证并升级分流…",()->{CloudPublisher.upgrade(a.manager);CloudMonitor.check(a.manager,"publish");a.ui(()->{render();a.toast("分流已升级，请刷新客户端订阅",Notice.Kind.SUCCESS);});})).show();}
 void restoreRouting(){new android.app.AlertDialog.Builder(a).setTitle("恢复升级前固定订阅？").setMessage("将用本机加密备份替换当前发布内容，固定地址不变。客户端刷新后生效。").setNegativeButton("取消",null).setPositiveButton("恢复",(d,w)->a.task("恢复并核对固定订阅…",()->{CloudPublisher.restoreRouting(a.manager);CloudMonitor.check(a.manager,"publish");a.ui(()->{render();a.toast("已恢复，请刷新客户端订阅",Notice.Kind.SUCCESS);});})).show();}
 void publish(){a.task("发布最近已就绪节点…",()->{JSONObject latest=null;for(int i=a.manager.records().length()-1;i>=0;i--){JSONObject r=a.manager.records().getJSONObject(i);if(r.optString("phase").equals("subscription-ready")){latest=r;break;}}if(latest==null)throw new java.io.IOException("没有已就绪节点");a.manager.check(latest);java.util.Map<String,Object> actual=Configs.parse(Book.download(latest.getString("url")));CloudPublisher.publish(a.manager,new JSONObject(Configs.routing(Configs.parse(a.manager.asset("config.yaml")),actual)));CloudMonitor.check(a.manager,"publish");a.ui(()->{render();a.toast("已发布，客户端刷新固定订阅即可",Notice.Kind.SUCCESS);});});}
 void edit(){a.enterDetail("固定入口设置","订阅",()->editor());}
 void editor(){a.body.removeAllViews();JSONObject cfg=CloudPublisher.config(a.manager);LinearLayout c=a.card("固定入口连接","管理密钥与只读订阅地址分开存储，均在手机加密保存。");EditText base=a.field(c,"服务根地址（HTTPS）",cfg==null?"":cfg.optString("base"),false),url=a.field(c,"固定只读订阅地址",cfg==null?"":cfg.optString("url"),true),admin=a.field(c,"管理密钥（留空保留）","",true);CheckBox auto=new CheckBox(a);auto.setText("新节点核验成功后自动替换固定订阅");auto.setTextSize(16);auto.setTextColor(a.INK);auto.setMinHeight(a.dp(48));auto.setChecked(cfg!=null&&cfg.optBoolean("auto_latest"));a.tint(auto);c.addView(auto);c.addView(a.label("开启后，新节点会覆盖原合并内容。保存设置不会切换代理客户端。",12,a.MUTED));TextView error=a.label("",14,a.DANGER);error.setVisibility(android.view.View.GONE);c.addView(error);
  a.button(c,"验证并保存",MainActivity.Tone.PRIMARY,()->{String b=base.getText().toString().trim(),u=url.getText().toString().trim(),key=admin.getText().toString();try{java.net.URI parsed=new java.net.URI(b);if(!"https".equals(parsed.getScheme())||parsed.getHost()==null||parsed.getUserInfo()!=null||parsed.getRawQuery()!=null||parsed.getRawFragment()!=null||(!parsed.getRawPath().isEmpty()&&!parsed.getRawPath().equals("/")))throw new Exception();}catch(Exception e){base.setError("请输入 HTTPS 服务根地址");return;}try{SubscriptionLinks.valid(u);}catch(Exception e){url.setError("请输入有效订阅地址");return;}if(key.isEmpty()&&(cfg==null||cfg.optString("admin").isEmpty())){admin.setError("请填写管理密钥");return;}boolean on=auto.isChecked();a.task("验证固定入口…",()->{try{JSONObject old=CloudPublisher.config(a.manager);JSONObject next=old==null?new JSONObject():new JSONObject(old.toString());next.put("base",b.replaceAll("/+$","")).put("url",u).put("admin",key.isEmpty()&&old!=null?old.optString("admin"):key).put("auto_latest",on);CloudPublisher.call(next,"GET","/api/status",null);a.manager.data.put("cloud",next);a.manager.data.remove("cloud_monitor");a.manager.save();CloudMonitor.check(a.manager,"settings");a.ui(()->{admin.setText("");a.toast("入口已验证并加密保存",Notice.Kind.SUCCESS);a.onBackPressed();});}catch(Exception e){a.ui(()->{error.setText("验证失败："+Book.safeMessage(e)+"。已保留输入，请检查网络或管理密钥后重试。");error.setVisibility(android.view.View.VISIBLE);});}});});
 }
}
